import{_ as o,C as n,o as a,c as i,E as r,a2 as s}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"A Trusted Path Proves Provenance, Not Approval","description":"","frontmatter":{"title":"A Trusted Path Proves Provenance, Not Approval","date":"2026-08-27","column":"open-source-engineering","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"什么时候，被调用的技能才能成为授权证据，又不让仓库文本或伪造路径冒充用户意图？","summary":"A merged OpenAI Codex Guardian v2 change records an actual invocation in the host and then verifies provenance through canonical trusted roots. The mechanism establishes bounded invocation origin, not safe content, immutable bytes or contemporaneous approval.","sources":["research/analysis/Q-20260827-03-host-verified-skill-invocation-provenance.md"],"item_id":"Q-20260827-03","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-27-trusted-path-proves-provenance-not-approval-cover-v2.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/engineering/2026-08-27-trusted-path-proves-provenance-not-approval.md","filePath":"en/engineering/2026-08-27-trusted-path-proves-provenance-not-approval.md","lastUpdated":1788162175000}'),c={name:"en/engineering/2026-08-27-trusted-path-proves-provenance-not-approval.md"};function d(l,e,h,u,p,v){const t=n("ArticleCover");return a(),i("div",null,[r(t,{image:"/assets/covers/daily-2026-08-27-trusted-path-proves-provenance-not-approval-cover-v2.png",kicker:"Open-source Engineering · Daily Research",title:"A Trusted Path Proves Provenance, Not Approval",summary:"A merged OpenAI Codex Guardian v2 change records an actual invocation in the host and then verifies provenance through canonical trusted roots. The mechanism establishes bounded invocation origin, not safe content, immutable bytes or contemporaneous approval.",version:"Q-20260827-03",status:"Daily Runtime V5 · 2026-08-27",languageHref:"/zh/engineering/2026-08-27-trusted-path-proves-provenance-not-approval",languageLabel:"中文"}),e[0]||(e[0]=s('<h1 id="a-trusted-path-proves-provenance-not-approval" tabindex="-1">A Trusted Path Proves Provenance, Not Approval <a class="header-anchor" href="#a-trusted-path-proves-provenance-not-approval" aria-label="Permalink to &quot;A Trusted Path Proves Provenance, Not Approval&quot;">​</a></h1><p>A skill can encode a user&#39;s preconfigured way of working and may provide useful context for an authorization decision. But a skill name, displayed path or repository-embedded tag cannot automatically become user authority. The repository under review can forge those strings, and a symlink can make a trusted-looking path resolve outside the expected root.</p><p>A merged OpenAI Codex Guardian v2 change demonstrates a stricter boundary. A skill becomes candidate evidence only after the host observes its invocation. The host then resolves the resource, canonicalizes both candidate and trusted roots, and requires the real file to remain under a user-owned root managed by the host. Repository skills and symlink escapes do not gain equivalent status through this path.</p><p>The core conclusion is: <strong>an invoked skill should influence authorization only after the host records the actual invocation and verifies resource provenance against an authority-owned trusted root. Canonical location proves a bounded origin under that trust model, not content identity, semantic safety, immutability or contemporaneous user approval.</strong></p><h2 id="prove-the-invocation-occurred-before-interpreting-it" tabindex="-1">Prove the invocation occurred before interpreting it <a class="header-anchor" href="#prove-the-invocation-occurred-before-interpreting-it" aria-label="Permalink to &quot;Prove the invocation occurred before interpreting it&quot;">​</a></h2><p>A skill existing on disk does not mean it participated in the current action. A skill body claiming “the user approved this” does not mean the host observed an invocation. Authorization evidence should begin with an occurrence: which execution, at what time, through which host, loaded which resource.</p><p>The selected implementation covers explicit and implicit skill invocation, but both pass through a host-controlled contributor. What becomes evidence is the observed invocation, not the name or body. That ordering blocks a circular path in which the object under review manufactures trusted-looking skill markup and thereby supplies its own authorization evidence.</p><p>Occurrence still does not equal approval. An invocation may result from old configuration, a broad policy or automatic selection. It establishes that the skill entered the current process. Why the skill is trusted, which content ran and whether it authorizes this action remain separate questions.</p><h2 id="canonical-trusted-roots-answer-an-origin-question" tabindex="-1">Canonical trusted roots answer an origin question <a class="header-anchor" href="#canonical-trusted-roots-answer-an-origin-question" aria-label="Permalink to &quot;Canonical trusted roots answer an origin question&quot;">​</a></h2><p>Textual path checks are easy to fool. A string beginning with a directory name does not prove that its resolved file remains there. Symlinks can cross directory boundaries, while relative paths and platform normalization can create ambiguity.</p><p>The public implementation canonicalizes both skill resources and roots, checks that the real file remains under a canonical trusted root, requires a file and applies path-length bounds. The question changes from “what does this path look like?” to “where did the host actually resolve it?” Maintainer tests cover user-owned skills, a forged repository skill, symlink escape, deduplication and evidence limits.</p><p>Who controls the root is equally important. Directory containment has authorization meaning only when the root belongs to an authority-owned trust boundary. If a repository can declare a new trusted root for itself, provenance qualification collapses back into self-attestation.</p><h2 id="path-only-evidence-reduces-risk-and-loses-content-identity" tabindex="-1">Path-only evidence reduces risk and loses content identity <a class="header-anchor" href="#path-only-evidence-reduces-risk-and-loses-content-identity" aria-label="Permalink to &quot;Path-only evidence reduces risk and loses content identity&quot;">​</a></h2><p>Guardian receives a bounded, deduplicated list of canonical paths rather than privileged copies of full skill bodies. That reduces two surfaces: prompt injection through large or adversarial content, and unbounded consumption of the review budget.</p><p>The tradeoff is that a path cannot answer which bytes ran. If a skill changes after invocation, a later audit sees the same location without proof of historical content. When replay or exact attribution matters, the invocation record should include a content digest, immutable version identity or signed snapshot. Path provenance must not substitute for content identity.</p><p>Evidence bounds must also be visible. Count, byte or token budgets may omit later trusted invocations. The limit is a legitimate safety measure, but it means the record is a bounded provenance set rather than complete history. An approver should know whether truncation occurred instead of interpreting absence as non-occurrence.</p><h2 id="five-evidence-dimensions-must-not-substitute-for-one-another" tabindex="-1">Five evidence dimensions must not substitute for one another <a class="header-anchor" href="#five-evidence-dimensions-must-not-substitute-for-one-another" aria-label="Permalink to &quot;Five evidence dimensions must not substitute for one another&quot;">​</a></h2><p>A durable authorization receipt should distinguish at least five questions:</p><ol><li>Occurrence: did the host observe this skill invocation?</li><li>Provenance: did the resolved resource fall under an authority-owned trusted root?</li><li>Content identity: which exact bytes or version were invoked?</li><li>Semantic safety: do those instructions permit the current capability and target?</li><li>Current approval: did a human or governing policy authorize this specific action?</li></ol><p>The Guardian change strengthens the first two and narrows privileged content exposure by passing paths. It does not automatically establish the other three. User ownership of a skill file does not mean the user reviewed today&#39;s version. Trusted location does not mean the instructions are current, conflict-free or within scope.</p><p>Engineering review should therefore avoid asking the overly broad question “is this skill trusted?” Ask which fact is being established, who produced the evidence, and which execution, resource version and time it binds. If the answer is only “the path is under a trusted directory,” the conclusion must stop at provenance.</p><h2 id="design-the-record-for-audit-and-revocation" tabindex="-1">Design the record for audit and revocation <a class="header-anchor" href="#design-the-record-for-audit-and-revocation" aria-label="Permalink to &quot;Design the record for audit and revocation&quot;">​</a></h2><p>Long-term audit needs an execution identity, canonical path, trusted-root decision, content digest, evidence-truncation flag and timestamp. When a skill changes, is removed or its root loses trust, the system should state whether historical evidence remains valid, future use requires reapproval, or downstream eligibility is revoked immediately.</p><p>The selected evidence is a merged implementation and maintainer tests, not independent validation of Guardian decision correctness. Trusted roots also depend on local filesystem and configuration correctness; they are not cryptographic provenance. The mechanism is a strong but bounded starting point: prevent repository text from impersonating user origin, then make other evidence layers carry responsibility for content and approval.</p><p><strong>Primary evidence:</strong> <a href="https://github.com/openai/codex/commit/b68acc4d4b56fdfa1d5b6a2c36102c66876e0c46" target="_blank" rel="noreferrer">OpenAI Codex merged commit b68acc4d</a>. The implementation and tests support observed invocation, canonical trusted-root provenance and bounded path evidence. They do not prove content safety, immutability or universal authorization.</p>',25))])}const b=o(c,[["render",d]]);export{g as __pageData,b as default};
